#!/bin/bash
# Slurm job for the 2xMI350X_EPYC_9655_pytorch_f16173d system (2 nodes x 8 GPUs).
# Edit CONT, DATADIR, LOGDIR and the partition below, then: sbatch job.sh
# Generated by the submission packaging tool; see README.md section 5.

#SBATCH --nodes=2
#SBATCH --ntasks-per-node=1
#SBATCH --exclusive
#SBATCH --job-name=dlrmv4_mlperf
#SBATCH --output=dlrmv4_%j.out
#SBATCH --partition=<YOUR_PARTITION>
# #SBATCH --time=<HH:MM:SS>    # uncomment and size it to NEXP runs

set -x

export CONT="<ROCM_MLPERF_CONTAINER>"
export DATADIR=/path/to/dataset
export LOGDIR=/path/to/results
case "${CONT}|${DATADIR}|${LOGDIR}" in
  *"<"*|*/path/to/*) echo "edit CONT, DATADIR and LOGDIR in job.sh first" >&2; exit 1 ;;
esac
export DGXSYSTEM=MI350X_02x08x1024
export NEXP=${NEXP:-1}                    # number of timed runs

export ROOT_SEED=${ROOT_SEED:-$RANDOM}

srun --ntasks-per-node=1 bash run_with_docker_slurm.sh
